## Do not edit this header; it is regenerated by the split script.


#' Build the standard fit identifier string.
#'
#' Format: `{resolution}-Iteration{iteration}-PA1:{PAratio}DO:{distOrder}-Seed{seed}[-{weight_scheme}]`.
#' This is the single source of truth for the pattern - every script that
#' writes or reads a per-fit artifact (model, test data, metrics CSV,
#' prediction raster, threshold mask) should build its filename via this,
#' and parse one back via `fname_parse()`.
#'
#' @param resolution Character, e.g. '1-3arc', '1arc', '3arc'.
#' @param iteration Integer or character, 0 or 1.
#' @param PAratio Numeric or character - the "X" in "1:X" (e.g. 1, 2.5, 1.079).
#'   Also accepts a leading "1:" and strips it, so callers can pass either form.
#' @param distOrder Numeric or character - the "Y" in "DO:Y". Accepts a leading
#'   "DO:" and strips it.
#' @param seed Integer or character.
#' @param weight_scheme Character. Empty, 'W0', or 'W...'; appended as
#'   `-{weight_scheme}` only when non-empty and not 'W0'.
fname_build <- function(resolution, iteration, PAratio, distOrder, seed, weight_scheme = ''){
  pa <- sub('^1:', '', as.character(PAratio))
  do <- sub('^DO:', '', as.character(distOrder))
  w  <- if(nzchar(weight_scheme) && weight_scheme != 'W0') paste0('-', weight_scheme) else ''
  sprintf('%s-Iteration%s-PA1:%sDO:%s-Seed%s%s', resolution, iteration, pa, do, seed, w)
}

#' Regex matching the standard fit identifier.
#'
#' Capture groups: 1 resolution, 2 iteration, 3 PAratio, 4 distOrder, 5 seed,
#' 6 weight_scheme (optional, includes the leading hyphen). Not anchored to
#' `.csv`/`.rds`/`.tif` so it can match a bare id or a file basename alike.
FNAME_RE <- '^(.+)-Iteration([0-9]+)-PA1:([0-9.]+)DO:([0-9.]+)-Seed([0-9]+)(-[A-Za-z0-9_]+)?$'

#' Parse a fit identifier (or a filename holding one) into its parts.
#'
#' Returns a one-row data.frame; unparseable input returns a row of NAs.
#' Any extension and trailing suffix after the id (e.g. `-Pr.tif`,
#' `-thresholds.tif`, `-dca.csv`) is stripped before matching.
fname_parse <- function(x){
  # Strip only KNOWN extensions - PAratio contains a dot (e.g. 1.079), so a
  # greedy `\.[^.]+$` would eat part of the id instead of the extension.
  bn <- sub('-(Pr|AOA|thresholds|dca)$', '',
            sub('\\.(csv|rds|tif|gpkg|txt|rda|rdata|RData)$', '', basename(x), ignore.case = TRUE))
  m <- regmatches(bn, regexec(FNAME_RE, bn))[[1]]
  if(length(m) < 6){
    return(data.frame(resolution = NA_character_, iteration = NA_integer_,
                       PAratio = NA_real_, distOrder = NA_real_, seed = NA_integer_,
                       weight_scheme = NA_character_, stringsAsFactors = FALSE))
  }
  data.frame(
    resolution    = m[2],
    iteration     = as.integer(m[3]),
    PAratio       = as.numeric(m[4]),
    distOrder     = as.numeric(m[5]),
    seed          = as.integer(m[6]),
    weight_scheme = if(length(m) >= 7 && nzchar(m[7])) sub('^-', '', m[7]) else NA_character_,
    stringsAsFactors = FALSE
  )
}

rastReader <- function(x, p2proc){

  # create paths for the first level of files. 
  f <- file.path(p2proc, x, list.files(file.path(p2proc, x), pattern = '.tif$'))

  # create paths for the geomorphology files.
  geo_f <- file.path(p2proc, x, 'geomorphology',
                     list.files(file.path(p2proc, x, 'geomorphology')))
  
  geo_f <- geo_f[! grepl('D8pntr|basins|DEM', geo_f) ] # remove the D8pntr & Basins 
  
  # combine the file paths
  f <- c(f, geo_f)
  s <- terra::rast(f)
  
}


ensure_multipolygons <- function(X) { # @ stackoverflow
  tmp1 <- tempfile(fileext = ".gpkg")
  tmp2 <- tempfile(fileext = ".gpkg")
  st_write(X, tmp1)
  gdalUtilities::ogr2ogr(tmp1, tmp2, f = "GPKG", nlt = "MULTIPOLYGON")
  Y <- st_read(tmp2)
  st_sf(st_drop_geometry(X), geom = st_geometry(Y))
}


#' Split text across multiple lines for use in a text grob
#' @params x a character vector which should be split out
#' @parms width the number of characters which each line should contain 
newliner <- function(x, width){
  
  # determine how many lines the text will be split across. 
  lines <- floor(nchar(x)/ width); wc_line <- ceiling(nchar(x)/lines)
  theo_cuts <- c(1, (wc_line * seq(lines))[1:lines-1])
  
  # determine sensible cuts for the words. Essentially just use the existing spaces.
  emp_cuts <- vector(mode = 'double', length = lines)
  for (i in seq(theo_cuts)){ # determine sensible cuts for the words. 
    emp_cuts[i] <- which(charToRaw(x) == '20')[
      which.min(abs(theo_cuts[i] - which(charToRaw(x) == '20')))]
  } 
  emp_cuts[1] <- 1
  end_cuts <- c(emp_cuts[2:length(emp_cuts)] - 1, nchar(x))
  
  # now we can just iterate through the string with a loop adding the newline
  # operator as required.
  new <- vector(mode = 'list', length = lines)
  for (i in seq(emp_cuts)){
    new[i] <- stringr::str_trim(rawToChar(charToRaw(x)[emp_cuts[i]:end_cuts[i]]))
  }
  newlined <- paste(new, collapse = '\n')
  
  # new <- list(emp_cuts, end_cuts)
  return(newlined)
  
}


#' Classify historic observations records in groups based on event date and geographic proximity
#' 
#' @description Simply measure the distance between observations that were made 
#' on the same day and bin points within 50m of one another. 
#' @param x a list of sf/tibble/dataframes with more than one record per day. 
HistObsGrps <- function(x){
  
  # calculate distances between all points
  dists <- st_distance(x)
  
  # and converts from a distances object to a simple numeric matrix. which works
  # the fns below. 
  dists <- matrix(as.numeric(dists), nrow = nrow(dists), byrow = TRUE)
  
  # tag points which we want connected - those within 50m of each other. 
  adj_matrix <- as.matrix(dists <= 50)
  graph <- igraph::graph_from_adjacency_matrix(adj_matrix, mode = "undirected") 
  
  # we can extract each 'grp' (including unconnected individuals)
  grps <- split(igraph::V(graph), igraph::components(graph)$membership)
  grps <- lapply(grps, \(x) setNames(
    data.frame(as.numeric(x)),
    nm = 'Indv')
  ) |>
    data.table::rbindlist(idcol = 'Obs.Grp') 
  
  grps <- grps[order(grps$Indv),]
  dplyr::mutate(x, 
                Obs.grp = grps$Obs.Grp, .before = 'geometry'
  )
}

#' Map a nominal resolution to the file-naming string used across results/ and data/
res_string <- function(resolution){
  switch(
    as.character(resolution),
    "3" = "3m",
    "10" = "1-3arc",
    "30" = "1arc",
    "90" = "3arc",
    stop("Input to `resolution` invalid. Need be one of: 3, 10, 30, 90")
  )
}

